begin;
do $$
declare uid uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();plat uuid:=gen_random_uuid();a uuid:=gen_random_uuid();p1 uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();op uuid:=gen_random_uuid();job public.subscription_changes;blocked boolean;today date:=(now() at time zone 'America/Sao_Paulo')::date;i integer;
begin
 insert into auth.users(id,email) values(uid,'subscription-check@example.invalid');
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,uid,now(),now());
 insert into public.admins(user_id,email) values(uid,'subscription-check@example.invalid');
 insert into public.platforms(id,slug,name) values(plat,'subtest-'||substr(plat::text,1,8),'Subscription fixture');
 insert into public.plans(id,platform_id,code,name,price_cents) values(p1,plat,'CURRENT','Current',10000),(p2,plat,'NEXT','Next',20000);
 insert into public.accounts(id,platform_id,external_id,plan_id,billing_day) values(a,plat,gen_random_uuid()::text,p1,10);
 insert into public.charges(account_id,period,due_on,amount_cents) values(a,date '2020-01-01',date '2020-01-10',10000);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 perform public.schedule_subscription_change(a,p2,null,10000,20000,10,today,op,null,null);
 perform public.schedule_subscription_change(a,p2,null,10000,20000,10,today,op,null,null);
 select * into job from public.subscription_changes where id=op;
 if job.effective_on<=today or job.new_price_cents<>20000 or (select plan_id from public.accounts where id=a)<>p1 or (select count(*) from public.subscription_changes where id=op)<>1 then raise exception 'Schedule or replay failed';end if;
 if (job.quote->>'total_days')::int<>(job.quote->>'used_days')::int+(job.quote->>'remaining_days')::int then raise exception 'Day count invalid';end if;
 blocked:=false;begin perform public.schedule_subscription_change(a,p2,null,9999,20000,10,today,gen_random_uuid(),null,null);exception when serialization_failure then blocked:=true;end;if not blocked then raise exception 'Stale quote accepted';end if;
 blocked:=false;begin update public.accounts set plan_id=p2 where id=a;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Direct plan change accepted';end if;
 blocked:=false;begin update public.accounts set billing_day=11 where id=a;exception when invalid_parameter_value then blocked:=true;end;if not blocked then raise exception 'Billing day changed while pending';end if;
 blocked:=false;begin perform public.claim_subscription_changes();exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Admin can claim worker jobs';end if;
 perform public.cancel_subscription_change(op);
 if (select status from public.subscription_changes where id=op)<>'cancelled' then raise exception 'Cancellation failed';end if;
 op:=gen_random_uuid();perform public.schedule_subscription_change(a,p2,null,10000,20000,10,today,op,null,null);
 update public.subscription_changes set effective_on=today where id=op;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 select * into job from public.claim_subscription_changes() where id=op;
 if job.status<>'processing' or job.attempts<>1 then raise exception 'Claim failed';end if;
 perform public.finish_subscription_change(op,gen_random_uuid(),null);
 if (select status from public.subscription_changes where id=op)<>'processing' then raise exception 'Wrong lease accepted';end if;
 perform public.finish_subscription_change(op,job.claim_token,null);perform public.finish_subscription_change(op,job.claim_token,null);
 if (select plan_id from public.accounts where id=a)<>p2 or (select count(*) from public.audit_log where action='subscription.apply' and data->>'operation'=op::text)<>1 then raise exception 'Apply or replay failed';end if;
 if (select amount_cents from public.charges where account_id=a)<>10000 then raise exception 'Existing charge changed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 op:=gen_random_uuid();perform public.schedule_subscription_change(a,p1,null,20000,10000,10,today,op,null,null);update public.subscription_changes set effective_on=today where id=op;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 for i in 1..5 loop
  update public.subscription_changes set retry_after=null where id=op;
  select * into job from public.claim_subscription_changes() where id=op;
  perform public.finish_subscription_change(op,job.claim_token,'Fixture failure');
 end loop;
 if (select status from public.subscription_changes where id=op)<>'failed' or (select attempts from public.subscription_changes where id=op)<>5 then raise exception 'Retry exhaustion failed';end if;
 if exists(select 1 from public.claim_subscription_changes() where id=op) then raise exception 'Exhausted job claimed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 perform public.retry_subscription_change(op);
 if (select attempts from public.subscription_changes where id=op)<>0 or (select status from public.subscription_changes where id=op)<>'scheduled' then raise exception 'Manual retry failed';end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 select * into job from public.claim_subscription_changes() where id=op;
 update public.subscription_changes set attempts=5,lease_until=now()-interval '1 minute' where id=op;
 perform public.claim_subscription_changes();
 if (select status from public.subscription_changes where id=op)<>'failed' then raise exception 'Crashed final attempt stuck processing';end if;
 if has_function_privilege('authenticated','public.finish_subscription_change(uuid,uuid,text)','execute') or has_table_privilege('authenticated','public.subscription_changes','insert') then raise exception 'Excess privileges';end if;
end;$$;
